// src/client/recovery/incident-api.ts
/** 请求选项（与 recovery 一致的长操作超时；文案沿用 error.recoveryTimeout）。 */
const INCIDENT_OPTS = {
	timeoutMs: LONG_REQUEST_TIMEOUT_MS,
	timeoutKey: "error.recoveryTimeout"
};
/** 事故恢复（崩溃归因 + 救援模式）浏览器半数据入口。 */
var IncidentApi = class {
	t;
	constructor(t) {
		this.t = t;
	}
	/** GET /crash：上次启动是否异常 + 归因 + 建议动作 + 最后正常时刻。 */
	async crash() {
		return getJson(INCIDENT_API.crash, this.t, INCIDENT_OPTS);
	}
	/** GET /rescue：救援模式状态。 */
	async rescueStatus() {
		return getJson(INCIDENT_API.rescue, this.t, INCIDENT_OPTS);
	}
	/**
	* POST /rescue {action:on, confirm:true}：进入救援模式。
	* confirm 必须由调用方在显式确认弹窗后传入 —— 本层绝不代填。
	*/
	async rescueOn() {
		return postJson(INCIDENT_API.rescue, {
			action: "on",
			confirm: true
		}, this.t, INCIDENT_OPTS);
	}
	/** POST /rescue {action:off}：退出救援模式（从备份完整还原）。 */
	async rescueOff() {
		return postJson(INCIDENT_API.rescue, { action: "off" }, this.t, INCIDENT_OPTS);
	}
};
